import axios from "axios";

import {
  ForecastApiResponse,
  ForecastEntity,
  ForecastFilters,
  ForecastRecord,
  ForecastScenario,
  ForecastScenarioApiResponse,
  ForecastStatistics,
} from "../types/forecast.types";

class ForecastService {
  private readonly baseUrl = "/api";

  /**
   * =====================================================
   * FORECAST DATA
   * =====================================================
   */

  /**
   * Get normal/baseline forecast data.
   *
   * GET /api/forecast-data
   */
  async getForecastData(): Promise<ForecastApiResponse> {
    const response =
      await axios.get<ForecastApiResponse>(
        `${this.baseUrl}/forecast-data`
      );

    return response.data;
  }

  /**
   * Get all scenario forecast data.
   *
   * GET /api/scenario-data
   *
   * The backend returns:
   *
   * actual
   * weather_hot_dry
   * weather_hot_wet
   * weather_cold_dry
   * weather_cold_wet
   */
  async getScenarioData(): Promise<ForecastScenarioApiResponse> {
    const response =
      await axios.get<ForecastScenarioApiResponse>(
        `${this.baseUrl}/scenario-data`
      );

    return response.data;
  }

  /**
   * =====================================================
   * ENTITIES
   * =====================================================
   */

  /**
   * Get all forecast entities from the backend.
   *
   * We deliberately do NOT maintain a hard-coded list
   * such as entity_1, entity_2, entity_3...
   *
   * The backend is the source of truth.
   */
  async getEntities(): Promise<ForecastEntity[]> {
    const scenarioData =
      await this.getScenarioData();

    const daily = Array.isArray(
      scenarioData.daily
    )
      ? scenarioData.daily
      : [];

    const monthly = Array.isArray(
      scenarioData.monthly
    )
      ? scenarioData.monthly
      : [];

    const records = [
      ...daily,
      ...monthly,
    ];

    /**
     * Extract entity IDs.
     */
    const entityIds = records
      .map(
        (record) =>
          record.entity_id
      )
      .filter(
        (
          entityId
        ): entityId is string =>
          typeof entityId ===
            "string" &&
          entityId.trim().length > 0
      );

    /**
     * Remove duplicates.
     */
    const uniqueEntityIds =
      Array.from(
        new Set(entityIds)
      );

    /**
     * Convert backend IDs into
     * objects used by the UI.
     */
    return uniqueEntityIds.map(
      (entityId) => ({
        id: entityId,
        label: entityId,
      })
    );
  }

  /**
   * =====================================================
   * SCENARIO MAPPING
   * =====================================================
   */

  /**
   * Convert frontend scenario IDs to
   * backend scenario IDs.
   */
  private getBackendScenarioId(
    scenario: ForecastScenario
  ): string {
    switch (scenario) {
      case "actual":
        return "actual";

      case "hotdry":
        return "weather_hot_dry";

      case "hotwet":
        return "weather_hot_wet";

      case "colddry":
        return "weather_cold_dry";

      case "coldwet":
        return "weather_cold_wet";

      default:
        return "actual";
    }
  }

  /**
   * =====================================================
   * CHART DATA
   * =====================================================
   */

  /**
   * Get forecast chart data.
   */
  async getForecastChart(
    filters: ForecastFilters
  ): Promise<ForecastRecord[]> {
    return this.getFilteredRecords(
      filters
    );
  }

  /**
   * Get forecast table/results data.
   */
  async getForecastResults(
    filters: ForecastFilters
  ): Promise<ForecastRecord[]> {
    return this.getFilteredRecords(
      filters
    );
  }

  /**
   * =====================================================
   * STATISTICS
   * =====================================================
   */

  /**
   * Get forecast statistics.
   */
  async getStatistics(
    filters: ForecastFilters
  ): Promise<ForecastStatistics> {
    const records =
      await this.getFilteredRecords(
        filters
      );

    if (records.length === 0) {
      return {
        average: 0,
        peak: 0,
        projectedVolume: 0,
        horizon: 0,
      };
    }

    const values = records.map(
      (record) =>
        this.getMetricValue(
          record,
          filters.metric
        )
    );

    const total =
      values.reduce(
        (
          sum,
          value
        ) => sum + value,
        0
      );

    const average =
      total / values.length;

    const peak =
      Math.max(...values);

    return {
      average,
      peak,
      projectedVolume: total,
      horizon: records.length,
    };
  }

  /**
   * =====================================================
   * FILTERING
   * =====================================================
   */

  /**
   * Get the correct records according to:
   *
   * - Horizon
   * - Entity
   * - Scenario
   */
  private async getFilteredRecords(
    filters: ForecastFilters
  ): Promise<ForecastRecord[]> {
    /**
     * scenario-data contains ALL scenarios,
     * including Actual.
     */
    const scenarioData =
      await this.getScenarioData();

    const records =
      filters.horizon === "monthly"
        ? scenarioData.monthly
        : scenarioData.daily;

    const backendScenarioId =
      this.getBackendScenarioId(
        filters.scenario
      );

    const filteredRecords =
      records.filter(
        (record) =>
          record.entity_id ===
            filters.entityId &&
          record.scenario_id ===
            backendScenarioId
      );

    console.log(
      "[ForecastService] Filtering forecast:",
      {
        horizon:
          filters.horizon,

        entityId:
          filters.entityId,

        scenario:
          filters.scenario,

        backendScenarioId,

        totalRecords:
          records.length,

        filteredRecords:
          filteredRecords.length,
      }
    );

    return filteredRecords;
  }

  /**
   * =====================================================
   * METRIC MAPPING
   * =====================================================
   */

  /**
   * Convert the selected metric into
   * the actual numeric backend field.
   */
  private getMetricValue(
    record: ForecastRecord,
    metric: ForecastFilters["metric"]
  ): number {
    switch (metric) {
      case "burn":
        return Number(
          record.Input ?? 0
        );

      case "supply":
        return Number(
          record.Replenishment ?? 0
        );

      case "stockpile":
        return Number(
          record.Stockpile ?? 0
        );

      default:
        return Number(
          record.Input ?? 0
        );
    }
  }
}

const forecastService =
  new ForecastService();

export default forecastService;
